for p, new in ROWS.items():
    lines[row(p)] = new
text = "\n".join(lines)
def rep(old, new):
    global text
    n = text.count(old); assert n == 1, (n, old[:90]); text = text.replace(old, new)
rep("- **In every batch**, for the batch's own files (DECREV 3.3-3.6):", "- **In every batch**, for the batch's own files (DECREV 3.2-3.6):")
